import test from 'node:test';
import assert from 'node:assert/strict';
import * as A from '../src/index.js';

const flush = () => new Promise(resolve => queueMicrotask(resolve));
function setup(t, options={}) {
  const a = new A.LayoutDocument({ContentId:'a',Title:'Alpha',Content:{data:'alpha'}});
  const b = new A.LayoutDocument({ContentId:'b',Title:'Beta',Content:{data:'beta'}});
  const x = new A.LayoutAnchorable({ContentId:'x',Title:'Explorer'});
  const y = new A.LayoutAnchorable({ContentId:'y',Title:'Search'});
  const docs = new A.LayoutDocumentPane({Id:'docs',Children:[a,b]});
  const tools = new A.LayoutAnchorablePane({Id:'tools',DockWidth:220,Children:[x,y]});
  const root = new A.LayoutRoot(new A.LayoutPanel({Children:[tools,docs]}));
  const m = new A.DockingManager({Layout:root,AllowMixedOrientation:true,...options});
  t.after(()=>m.Dispose());m.ClearHistory();return{m,a,b,x,y,docs,tools,root};
}
function valid(m) { return A.validateLayout(m.Layout); }
function stable(m) { return JSON.stringify(A.snapshot(m.Layout), (key,value)=>['activeContentId','lastFocusedDocumentId','LastActivationTimeStamp','IsSelected'].includes(key)?undefined:value); }

test('GridLength matches pixel, star and auto semantics',()=>{assert.equal(A.GridLength.Parse(250).IsAbsolute,true);assert.equal(A.GridLength.Parse('*').Value,1);assert.equal(A.GridLength.Parse('2.5*').toString(),'2.5*');assert.equal(A.GridLength.Parse('Auto').IsAuto,true);assert.ok(A.GridLength.Parse('2*').Equals(new A.GridLength(2)));for(const v of[-1,Infinity,'-1*','calc(10px)','x',{}])assert.throws(()=>A.GridLength.Parse(v));});
test('show strategy uses upstream numeric flags',()=>{assert.deepEqual(A.AnchorableShowStrategy,{Most:1,Left:2,Right:4,Top:16,Bottom:32});});
test('events are removable and use sender/args',()=>{const s=new A.EventSignal(),sender={};let n=0;const off=s.add((who,args)=>{assert.equal(who,sender);n+=args.n;});s.emit(sender,{n:2});off();s.emit(sender,{n:3});assert.equal(n,2);});
test('observable properties emit changing before changed',()=>{const d=new A.LayoutDocument(),events=[];d.PropertyChanging.add((s,e)=>events.push(['before',s.Title,e.NewValue]));d.PropertyChanged.add((s,e)=>events.push(['after',s.Title,e.NewValue]));d.SetValue(A.LayoutContent.TitleProperty,'New');assert.deepEqual(events,[['before','','New'],['after','New','New']]);assert.equal(d.GetValue('Title'),'New');d.ClearValue('Title');assert.equal(d.Title,'');});
test('collections support indexing, replacement, ordering and removal',()=>{const c=new A.ObservableCollection([1,2,3]);c.Insert(1,4);c[0]=5;c.Move(3,0);assert.deepEqual([...c],[3,5,4,2]);assert.equal(c.Remove(4),true);assert.deepEqual(c.splice(1,1,9),[5]);assert.deepEqual(c.ToArray(),[3,9,2]);assert.equal(c.Count,3);assert.throws(()=>c.RemoveAt(99));});
test('typed reparenting detaches old owner and selection follows',t=>{const{m,a,docs}=setup(t);const pane=new A.LayoutDocumentPane();m.Layout.RootPanel.Children.Add(pane);pane.Children.Add(a);assert.equal(a.Parent,pane);assert.equal(docs.Children.Count,1);assert.equal(pane.SelectedContent,a);valid(m);});
test('cycles and wrong pane types are rejected before mutation',t=>{const{m,a,tools}=setup(t);assert.throws(()=>tools.Children.Add(a),/only anchorables/);assert.throws(()=>m.Layout.RootPanel.Children.Add(m.Layout.RootPanel),/cycles/);assert.equal(a.Parent.Id,'docs');valid(m);});
test('duplicate node and content identifiers are rejected on direct edits',t=>{const{m,a,b,docs}=setup(t);assert.throws(()=>b.ContentId=a.ContentId,/Duplicate/);assert.equal(b.ContentId,'b');assert.throws(()=>b.Id=a.Id,/Duplicate/);assert.throws(()=>docs.Children.Add(new A.LayoutDocument({ContentId:'a'})),/Duplicate/);assert.equal(docs.Children.Count,2);valid(m);});
test('one selected item per pane, active model vs content',t=>{const{m,a,b,docs}=setup(t);b.IsSelected=true;assert.equal(docs.SelectedContent,b);assert.equal(a.IsSelected,false);m.ActiveContent=a.Content;assert.equal(m.ActiveModel,a);assert.equal(a.IsActive,true);assert.equal(m.Layout.LastFocusedDocument,a);m.Activate(b);assert.equal(a.IsActive,false);assert.equal(b.IsActive,true);});
test('float and dock document restore original tab index',t=>{const{m,a,docs}=setup(t);const f=a.Float();assert.ok(f instanceof A.LayoutDocumentFloatingWindow);assert.equal(f.RootDocument,a);assert.equal(a.IsFloating,true);assert.equal(m.Layout.FloatingWindows.Count,1);a.Dock();assert.equal(a.Parent,docs);assert.equal(docs.Children[0],a);assert.equal(m.Layout.FloatingWindows.Count,0);valid(m);});
test('tool pane floats together and restores its tabs',t=>{const{m,x,y,tools}=setup(t);m.Float(tools);assert.ok(x.IsFloating&&y.IsFloating);assert.equal(m.Layout.FloatingWindows.Count,1);m.Dock(m.Layout.FloatingWindows[0]);assert.ok(!x.IsFloating&&!y.IsFloating);assert.equal(x.Parent,y.Parent);valid(m);});
test('floating root replacement is typed and atomic',()=>{const a=new A.LayoutDocument(),b=new A.LayoutDocument(),f=new A.LayoutDocumentFloatingWindow({RootDocument:a});assert.throws(()=>f.RootPanel=new A.LayoutAnchorablePane());assert.equal(f.RootDocument,a);f.RootDocument=b;assert.equal(a.Parent,null);assert.equal(f.RootDocument,b);});
test('capability flags gate model and command operations',t=>{const{m,a,x,docs}=setup(t);a.CanFloat=false;assert.equal(a.Float(),false);assert.equal(m.GetLayoutItemFromModel(a).FloatCommand.CanExecute(),false);a.CanClose=false;assert.equal(a.Close(),false);x.CanDockAsTabbedDocument=false;assert.equal(m.Dock(x,docs),false);x.CanHide=false;assert.equal(x.Hide(),false);a.CanMove=false;assert.equal(m.NewTabGroup(a),false);valid(m);});
test('disabled content cannot be activated, dragged, floated or docked',t=>{const{m,a,b}=setup(t);m.Activate(b);a.IsEnabled=false;assert.equal(m.Activate(a),false);assert.equal(m.Float(a),false);assert.equal(m.Dock(a),false);assert.equal(m.ActiveModel,b);});
test('document restrictions prohibit tool panes, root edges and auto-hide',t=>{const{m,a,tools}=setup(t);assert.equal(m.Dock(a,tools,'Center'),false);assert.equal(m.Dock(a,m.Layout,'Left'),false);assert.equal(m.ToggleAutoHide(a),false);valid(m);});
for(const side of ['Left','Right','Top','Bottom'])test(`tools dock at ${side} edge`,t=>{const{m,x}=setup(t);assert.ok(m.Dock(x,m.Layout,side));assert.equal(m._sideFor(x.Parent),side);assert.equal(x.IsDocked,true);valid(m);});
for(const side of ['Left','Right','Top','Bottom'])test(`document split ${side} and merge`,t=>{const{m,a,b,docs}=setup(t);assert.ok(m.Dock(a,docs,side));assert.notEqual(a.Parent,b.Parent);assert.ok(m.Dock(a,b.Parent,'Center'));assert.equal(a.Parent,b.Parent);valid(m);});
test('same-pane tab reordering handles forward and backward insertion',t=>{const{m,a,b,docs}=setup(t);m.Dock(a,docs,'Center',2);assert.deepEqual(docs.Children.ToArray(),[b,a]);m.Dock(a,docs,'Center',0);assert.deepEqual(docs.Children.ToArray(),[a,b]);});
test('tab group commands use visual horizontal/vertical semantics',t=>{const{m,a,b}=setup(t);m.GetLayoutItemFromModel(a).NewVerticalTabGroupCommand.Execute();assert.equal(a.Parent.Parent.Orientation,'Horizontal');assert.equal(m.GetLayoutItemFromModel(a).MoveToPreviousTabGroupCommand.CanExecute(),true);m.GetLayoutItemFromModel(a).MoveToPreviousTabGroupCommand.Execute();assert.equal(a.Parent,b.Parent);valid(m);});
test('mixed-orientation policy disables incompatible nesting',t=>{const{m,a,b,docs}=setup(t,{AllowMixedOrientation:false});const group=new A.LayoutDocumentPaneGroup({Orientation:'Horizontal'});m.Layout.RootPanel.ReplaceChild(docs,group);group.Children.Add(docs);m.Dock(a,docs,'Right');assert.equal(m.CanDockAt(a,b.Parent,'Bottom'),false);});
test('group auto-hide and pin restore original pane order',t=>{const{m,x,y,tools}=setup(t);assert.equal(x.ToggleAutoHide(),true);assert.ok(x.IsAutoHidden&&y.IsAutoHidden);assert.equal(x.Parent,y.Parent);assert.equal(x.Parent.Parent,m.Layout.LeftSide);assert.equal(m.ShowAutoHideWindow(x),true);assert.equal(m.AutoHideWindow.Model,x);assert.equal(x.ToggleAutoHide(),true);assert.deepEqual(tools.Children.ToArray(),[x,y]);assert.equal(m.AutoHideWindow,null);valid(m);});
test('auto-hide requires all pane children to permit it',t=>{const{m,x,y}=setup(t);y.CanAutoHide=false;assert.equal(x.ToggleAutoHide(),false);assert.equal(x.IsAutoHidden,false);valid(m);});
test('hide is reversible and differs from close',t=>{const{m,x,tools}=setup(t);assert.equal(x.Hide(),true);assert.equal(m.Layout.Hidden[0],x);assert.equal(x.IsVisible,false);assert.equal(m.Find('x'),x);x.Show();assert.equal(x.Parent,tools);assert.equal(x.IsVisible,true);x.Close();assert.equal(m.Find('x'),null);valid(m);});
test('cancelable closing runs model and manager handlers',t=>{const{m,a}=setup(t);let model=0,manager=0,closed=0;a.Closing.add((_s,e)=>{model++;e.Cancel=true;});m.DocumentClosing.add(()=>manager++);m.DocumentClosed.add(()=>closed++);assert.equal(a.Close(),false);assert.equal(model,1);assert.equal(manager,1);assert.equal(closed,0);assert.equal(m.Find('a'),a);});
test('cancelable hiding leaves content in place',t=>{const{m,x,tools}=setup(t);m.AnchorableHiding.add((_s,e)=>e.preventDefault());assert.equal(x.Hide(),false);assert.equal(x.Parent,tools);assert.equal(x.Hide(false),true);});
test('closing a floating tool group preflights cancellation atomically',t=>{const{m,x,y,tools}=setup(t);const f=m.Float(tools);y.Hiding.add((_s,e)=>e.Cancel=true);assert.equal(m.CloseFloatingWindow(f),false);assert.ok(x.IsFloating&&y.IsFloating);assert.equal(m.Layout.Hidden.Count,0);});
test('close all respects individual cancellation and CanClose',t=>{const{m,a,b}=setup(t);a.CanClose=false;assert.equal(m.CloseAll(),1);assert.equal(m.Find('a'),a);assert.equal(m.Find('b'),null);valid(m);});
test('JSON roundtrip retains content identity, flags and topology',t=>{const{m,a,x}=setup(t);const content=a.Content;a.Title='A < & " unicode Ω';a.CanClose=false;x.ToggleAutoHide();const json=m.SaveLayout();m.LoadLayout(json);assert.equal(m.Find('a').Content,content);assert.equal(m.Find('a').CanClose,false);assert.equal(m.Find('a').Title,a.Title);assert.equal(m.Find('x').IsAutoHidden,true);valid(m);});
test('XML roundtrip handles native sections, floats, hidden and entities',t=>{const{m,a,x,y}=setup(t);a.Title='α < " & \n';m.Float(a);x.Hide();y.ToggleAutoHide();const xml=m.SaveLayout('xml');assert.ok(xml.includes('<RootPanel'));assert.ok(xml.includes('<LayoutDocumentFloatingWindow'));assert.ok(xml.includes('&amp;'));assert.ok(!xml.includes('<Content>'));m.LoadLayout(xml);assert.equal(m.Find('a').Title,a.Title);assert.ok(m.Find('a').IsFloating);assert.ok(m.Find('x').IsHidden);assert.ok(m.Find('y').IsAutoHidden);valid(m);});
test('native minimal AvalonDock XML imports',t=>{const{m}=setup(t);m.LoadLayout(`<?xml version="1.0"?><LayoutRoot><RootPanel Orientation="Horizontal"><LayoutDocumentPane><LayoutDocument Title="A" ContentId="a" IsSelected="True" /></LayoutDocumentPane></RootPanel><TopSide/><RightSide/><LeftSide/><BottomSide/><FloatingWindows/><Hidden/></LayoutRoot>`);assert.equal(m.Find('a').Title,'A');valid(m);});
test('serialization callback resolves and cancels content',t=>{const{m}=setup(t);const xml=m.SaveLayout('xml');const serializer=new A.XmlLayoutSerializer(m),object={loaded:true};serializer.LayoutSerializationCallback.add((_s,e)=>{if(e.Model.ContentId==='a')e.Content=object;if(e.Model.ContentId==='b')e.Cancel=true;});serializer.Deserialize(xml);assert.equal(m.Find('a').Content,object);assert.equal(m.Find('b'),null);valid(m);});
test('serialization supports writer but not pretend filesystem overload',t=>{const{m}=setup(t);let out='';assert.equal(new A.XmlLayoutSerializer(m).Serialize({Write(value){out=value;}}),out);assert.ok(out.startsWith('<?xml'));assert.throws(()=>new A.XmlLayoutSerializer(m).Serialize('/tmp/file.xml'));});
test('invalid JSON import is atomic and prototype-safe',t=>{const{m}=setup(t);const initial=stable(m);for(const text of['{}','not-json',JSON.stringify({format:'avalondock-web',version:22,layout:{}}),m.SaveLayout().replace('"LayoutDocument"','"Script"'),m.SaveLayout().replace('"Title": "Alpha"','"__proto__": {"polluted":true}')]){assert.throws(()=>m.LoadLayout(text));assert.equal(stable(m),initial);}assert.equal({}.polluted,undefined);});
test('malformed or hostile XML is rejected without changing layout',t=>{const{m}=setup(t);const before=stable(m);for(const xml of['<LayoutRoot>','<!DOCTYPE x><LayoutRoot/>','<LayoutRoot>&evil;</LayoutRoot>','<LayoutRoot><Unknown /></LayoutRoot>','<LayoutRoot><RootPanel Orientation="Horizontal" Orientation="Vertical"/></LayoutRoot>','<LayoutRoot><RootPanel><LayoutDocumentPane><LayoutDocument ContentId="a" Title="&evil;"/></LayoutDocumentPane></RootPanel></LayoutRoot>']){assert.throws(()=>m.LoadLayout(xml));assert.equal(stable(m),before);}});
test('serializer rejects oversized and deeply nested inputs',t=>{const{m}=setup(t);assert.throws(()=>m.LoadLayout(' '.repeat(4*1024*1024+1)));const text='<LayoutRoot><RootPanel>'+('<LayoutPanel>'.repeat(66))+('</LayoutPanel>'.repeat(66))+'</RootPanel></LayoutRoot>';assert.throws(()=>m.LoadLayout(text),/limit/);});
test('undo/redo restore model structure and retained content',t=>{const{m,a}=setup(t);const content=a.Content;m.Float(a);assert.equal(m.CanUndo,true);m.Undo();assert.equal(m.Find('a').IsFloating,false);assert.equal(m.Find('a').Content,content);m.Redo();assert.equal(m.Find('a').IsFloating,true);valid(m);});
test('direct observable edits are coalesced into history',async t=>{const{m,a}=setup(t);a.Title='One';a.Title='Two';await flush();assert.equal(m._undo.length,1);m.Undo();assert.equal(m.Find('a').Title,'Alpha');});
test('selection alone is not a history operation',async t=>{const{m,a,b}=setup(t);m.Activate(a);m.Activate(b);await flush();assert.equal(m.CanUndo,false);});
test('transactions roll back exceptions and preserve content',t=>{const{m,a}=setup(t);const before=stable(m),content=a.Content;assert.throws(()=>m.Transaction('bad',()=>{m.Find('a').Title='Mutated';m.Float(m.Find('a'));throw new Error('cancel');}));assert.equal(stable(m),before);assert.equal(m.Find('a').Content,content);valid(m);});
test('BeginUpdate batches several changes into one undo',t=>{const{m,a,b}=setup(t);const update=m.BeginUpdate();a.Title='A!';b.Title='B!';update.Dispose();update.Dispose();assert.equal(m._undo.length,1);m.Undo();assert.equal(m.Find('a').Title,'Alpha');assert.equal(m.Find('b').Title,'Beta');});
test('history limit and redo invalidation',t=>{const{m}=setup(t,{HistoryLimit:2});for(let i=0;i<3;i++)m.AddDocument({ContentId:`new${i}`});assert.equal(m._undo.length,2);m.Undo();assert.ok(m.CanRedo);m.AddDocument({ContentId:'different'});assert.equal(m.CanRedo,false);});
test('observable sources add/remove documents and project styles',t=>{const{m}=setup(t,{LayoutItemContainerStyle:{CanClose:value=>!value.locked}});const source=new A.ObservableCollection();m.DocumentsSource=source;const data={ContentId:'bound',Title:'Bound',locked:true};source.Add(data);assert.equal(m.Find('bound').Content,data);assert.equal(m.Find('bound').CanClose,false);data.Title='Updated';data.locked=false;m.RefreshSources();assert.equal(m.Find('bound').Title,'Updated');assert.equal(m.Find('bound').CanClose,true);source.Remove(data);assert.equal(m.Find('bound'),null);valid(m);});
test('close removes source item and array RefreshSources reconciles changes',t=>{const{m}=setup(t);const data={id:'bound',title:'Bound'},source=[data];m.DocumentsSource=source;m.Find('bound').Close();assert.equal(source.length,0);source.push({id:'new',title:'New'});m.RefreshSources();assert.ok(m.Find('new'));});
test('source identities survive layout deserialization',t=>{const{m}=setup(t);const source=new A.ObservableCollection([{id:'bound',title:'Bound'}]);m.DocumentsSource=source;m.LoadLayout(m.SaveLayout());source.RemoveAt(0);assert.equal(m.Find('bound'),null);valid(m);});
test('layout insertion strategy can choose destination',t=>{const{m}=setup(t);const destination=new A.LayoutDocumentPane();m.Layout.RootPanel.Children.Add(destination);let before=0,after=0;m.LayoutUpdateStrategy={BeforeInsertDocument(root,doc){before++;destination.Children.Add(doc);return true;},AfterInsertDocument(){after++;}};const doc=m.AddDocument({ContentId:'strategic'});assert.equal(doc.Parent,destination);assert.equal(before,1);assert.equal(after,1);});
test('invalid handled insertion strategy rolls back',t=>{const{m}=setup(t);const before=stable(m);m.LayoutUpdateStrategy={BeforeInsertDocument(){return true;}};assert.throws(()=>m.AddDocument({ContentId:'lost'}),/without inserting/);assert.equal(stable(m),before);});
test('command CanExecuteChanged is raised when capability changes',t=>{const{m,a}=setup(t);const item=m.GetLayoutItemFromModel(a);let n=0;item.FloatCommand.CanExecuteChanged.add(()=>n++);a.CanFloat=false;assert.ok(n>0);assert.equal(item.FloatCommand.CanExecute(),false);});
test('independent managers reject accidental reparenting and support explicit transfer',t=>{const{m,a}=setup(t);const second=new A.DockingManager();t.after(()=>second.Dispose());assert.throws(()=>second.Layout.RootPanel.Children[0].Children.Add(a),/TransferTo/);assert.equal(m.TransferTo(second,a),true);assert.equal(m.Find('a'),null);assert.equal(second.Find('a'),a);valid(m);valid(second);});
test('storage APIs are harmless without a storage provider',t=>{const{m}=setup(t);assert.equal(m.SaveToStorage('test'),false);assert.equal(m.LoadFromStorage('test'),false);});
test('Dispose releases ownership and rejects future transactions',t=>{const{m}=setup(t);m.Dispose();assert.equal(m.Layout.Manager,null);assert.throws(()=>m.AddDocument({Title:'Disposed'}),/disposed/);m.Dispose();});
